using System.Text.Json;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evals.Tests;

public class QualityTests
{
    private static readonly string GoldenPath =
        Path.Combine(AppContext.BaseDirectory, "Quality", "golden.json");

    public static IEnumerable<object[]> GoldenCases()
    {
        var json = File.ReadAllText(GoldenPath);
        var cases = JsonSerializer.Deserialize<List<GoldenCase>>(json,
            new JsonSerializerOptions { PropertyNameCaseInsensitive = true })!;

        foreach (var c in cases)
            yield return new object[] { c.Id, c };
    }

    [Theory]
    [MemberData(nameof(GoldenCases))]
    public async Task EvaluateCase(string id, GoldenCase goldenCase)
    {
        // Arrange: send the user message to the agent and collect the response.
        var response = await GetAgentResponseAsync(goldenCase.UserMessage);

        // Assert: verify expected traits are present in the response.
        Assert.NotNull(response);
        foreach (var trait in goldenCase.ExpectedTraits)
        {
            Assert.Contains(trait, response, StringComparison.OrdinalIgnoreCase);
        }
    }

    private static Task<string> GetAgentResponseAsync(string userMessage)
    {
        // TODO: Replace with actual agent invocation via the AppHost.
        // This placeholder returns the user message to allow the harness to compile and run.
        return Task.FromResult(userMessage);
    }
}

public record GoldenCase
{
    public string Id { get; init; } = string.Empty;
    public string UserMessage { get; init; } = string.Empty;
    public List<string> ExpectedTraits { get; init; } = new();
}

